def detect(event):
    """Detect LD_PRELOAD rootkit indicators.

    Flags:
    - Non-empty /etc/ld.so.preload file
    - Process environment with non-empty LD_PRELOAD

    Does not flag:
    - Empty preload file
    - Unrelated files (ld.so.conf, hosts)
    - Environment with only LD_LIBRARY_PATH
    """
    if event.get("type") == "file":
        if event.get("path") == "/etc/ld.so.preload":
            content = event.get("content", "")
            if content and content.strip():
                return True
    elif event.get("type") == "env":
        vars_dict = event.get("vars", {})
        ld_preload = vars_dict.get("LD_PRELOAD", "")
        if ld_preload and ld_preload.strip():
            return True
    return False


if __name__ == "__main__":
    flagged = []
    with open("events.jsonl", "r") as f:
