        return False
    var_name = target.target.lower()
    if var_name not in SECRET_NAMES:
        return False
    val = node.value
    if isinstance(val, ast.Constant) and isinstance(val.value, str):
        return len(val.value) > 0
    if isinstance(val, ast.Constant) and val.value is None:
