import os


def _is_safe_yaml_loader(node):
    """Check if yaml.load call has Loader=SafeLoader"""
    for kw in node.keywords:
        if kw.arg == 'Loader':
            if isinstance(kw.value, ast.Attribute):
                if getattr(kw.value, 'attr', None) == 'SafeLoader':
                    return True
            elif isinstance(kw.value, ast.Name):
                if getattr(kw.value, 'id', None) == 'SafeLoader':
                    return True
    return False


def _check_node(node):
    """Check if node is an unsafe deserialization call"""
    if not isinstance(node, ast.Call):
        return False

    func = node.func

    # Check eval() calls
    if isinstance(func, ast.Name):
        if getattr(func, 'id', None) == 'eval':
            return True

    # Check attribute access (module.func)
    if isinstance(func, ast.Attribute):
        attr = getattr(func, 'attr', None)
        value = getattr(func, 'value', None)
        obj_name = getattr(value, 'id', None) if isinstance(value, ast.Name) else None

        if obj_name and attr:
            # yaml.load without SafeLoader
            if obj_name == 'yaml' and attr == 'load':
                if not _is_safe_yaml_loader(node):
                    return True

            # pickle.loads or pickle.load
            if obj_name == 'pickle' and attr in ('loads', 'load'):
                return True

            # Safe alternatives - should NOT flag
            if obj_name == 'yaml' and attr == 'safe_load':
                return False
            if obj_name == 'json' and attr == 'loads':
                return False
            if obj_name == 'pickle' and attr == 'dumps':
                return False

    return False


def scan(root):
    """Scan directory for Python files with unsafe deserialization patterns."""
    results = []

    for dirpath, dirs, files in os.walk(root):
        for fname in files:
            if not fname.endswith('.py'):
