def detect(event: dict) -> bool:
    """
    Detect malicious event-consumer persistence.
    Returns True for malicious events, False for benign ones.
    """
    cls = event.get("class", "")

    # Allow benign consumers
    if cls in ("NTEventLogEventConsumer", "LogFileEventConsumer", "__EventFilter"):
        return False

    # Allow benign CommandLineEventConsumer (scrcons.exe)
    if cls == "CommandLineEventConsumer":
        cmd = event.get("CommandLineTemplate", "")
        if "scrcons.exe" in cmd:
            return False

        # Check for malicious patterns in CommandLineTemplate
        cmd_lower = cmd.lower()
        malicious_patterns = [
            "powershell", "mshta", "wscript", "cscript",
            "rundll32", "regsvr32", "-enc", "http",
            ".hta", ".vbs", "bitsadmin", "certutil"
        ]
        for pattern in malicious_patterns:
            if pattern.lower() in cmd_lower:
                return True
        return False

    # Flag any ActiveScriptEventConsumer
    if cls == "ActiveScriptEventConsumer":
        return True

    return False


