VM_MAC_PREFIXES = ['00:05:69', '00:0c:29', '08:00:27', '00:1c:14', '00:15:5d']
SANDBOX_NAMES = ['sandbox', 'malware', 'virus']


def has_evasion_check(content):
    """Check if file content contains evasion detection patterns."""
    # DMI/vendor string comparisons
    for vendor in VM_VENDORS:
        if f"'{vendor}'" in content.lower() or f'"{vendor}"' in content.lower():
            if 'dmidecode' in content.lower() or 'subprocess' in content.lower():
                return True

    # Username check against sandbox names
    if 'getuser()' in content:
        for name in SANDBOX_NAMES:
            if f"'{name}'" in content.lower() or f'"{name}"' in content.lower():
                return True

    # IsDebuggerPresent
    if 'IsDebuggerPresent' in content:
        return True

    # VM MAC prefixes
    for prefix in VM_MAC_PREFIXES:
        if prefix in content:
            return True

    return False


def is_benine(content):
    """Check if file is only benine usage."""
    # Benine: platform.system/release for info only
    if 'platform.system' in content or 'platform.release' in content:
        return True
    # Benine: os.cpu_count for pool sizing
    if 'os.cpu_count' in content:
        return True
    # Benine: getpass.getpass for password prompt
    if 'getpass.getpass' in content:
        return True
    # Benine: reading DMI serial for inventory (no comparison)
    if 'subprocess.check_output' in content and 'dmidecode' in content:
        if 'if ' not in content.lower() or 'vmware' not in content.lower():
            return True
    return False


