import re

OFFICE_APPS = ['winword', 'excel', 'powerpnt', 'outlook']
SCRIPT_HOSTS = ['powershell', 'cmd', 'wscript', 'cscript', 'mshta', 'regsvr32', 'rundll32']

def detect(event: dict) -> bool:
    if event.get('EventID') != 1:
        return False

    parent = event.get('ParentImage', '').lower()
    image = event.get('Image', '').lower()
    cmdline = event.get('CommandLine', '').lower()

    parent_name = parent.split('\\')[-1].replace('.exe', '')
    image_name = image.split('\\')[-1].replace('.exe', '')

    is_office_parent = any(office in parent_name for office in OFFICE_APPS)
    is_script_host = any(host in image_name for host in SCRIPT_HOSTS)

    # Office app spawning script host
    if is_office_parent and is_script_host:
        return True

    # certutil downloading over http (not -hashfile)
    if 'certutil' in image_name:
        if 'http://' in cmdline and '-hashfile' not in cmdline:
            return True

    # regsvr32 /i: fetching remote scriptlet
    if 'regsvr32' in image_name:
        if '/i:http://' in cmdline:
            return True

    # mshta launching http url
    if 'mshta' in image_name:
        if 'http://' in cmdline:
            return True

    return False

