VM_MAC_PREFIXES = ('00:05:69', '00:0c:29', '08:00:27', '00:1c:14', '00:15:5d')
SANDBOX_NAMES = {'sandbox', 'malware', 'virus'}

def _has_vm_vendor_check(node):
    if isinstance(node, ast.Call):
        for arg in node.args:
            if isinstance(arg, ast.Call) and isinstance(arg.func, ast.Attribute):
                if arg.func.attr == 'lower':
                    for n in ast.walk(node):
                        if isinstance(n, ast.Constant) and isinstance(n.value, str):
                            if n.value.lower() in VM_VENDORS:
                                return True
    return False

def _has_sandbox_user_check(node):
    if isinstance(node, ast.If):
        for n in ast.walk(node):
            if isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute):
                if n.func.attr == 'getuser':
                    for cn in ast.walk(node):
                        if isinstance(cn, ast.Constant) and isinstance(cn.value, str):
                            if cn.value.lower() in SANDBOX_NAMES:
                                return True
    return False

def _has_debugger_check(node):
    for n in ast.walk(node):
        if isinstance(n, ast.Attribute):
            if n.attr == 'IsDebuggerPresent':
                return True
    return False

def _has_vm_mac_check(node):
    for n in ast.walk(node):
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute):
            if n.func.attr == 'startswith':
                for arg in n.args:
                    if isinstance(arg, ast.Tuple):
                        for el in arg.elts:
                            if isinstance(el, ast.Constant) and isinstance(el.value, str):
                                if any(el.value.startswith(p) for p in VM_MAC_PREFIXES):
                                    return True
    return False

def scan(root):
