import re


def detect(event: dict) -> bool:
    """Detect encoded/obfuscated PowerShell invocations."""
    cmd = event.get("CommandLine", "")
    cmd_lower = cmd.lower()

    # Check if it's a powershell/pwsh invocation
    if not re.search(r"(powershell|pwsh)", cmd_lower):
        return False

    # Flag encoded/obfuscated patterns
    if re.search(r"-enc(oded|odedcommand)?\b", cmd_lower):
        return True
    if re.search(r"\s-e\s", cmd_lower):
        return True

    # Flag suspicious commands
    suspicious = ["iex", "invoke-expression", "downloadstring", "downloadfile", "frombase64string"]
    if any(s in cmd_lower for s in suspicious):
        return True

