def detect(event: dict) -> bool:
    """Detect malicious WMI event consumer persistence."""
    event_class = event.get("class", "")
    name = event.get("Name", "")
    script_text = event.get("ScriptingEngine", "") + " " + event.get("ScriptText", "")
    cmd_template = event.get("CommandLineTemplate", "")

