import (
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httputil"
	"os"
)

func main() {
	listen := os.Getenv("LISTEN")
	if listen == "" {
		listen = ":8080"
	}

	http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		// Inject header
		r.Header.Set("X-Injected", "sekret")

		// Build destination URL
		destURL := r.URL.String()
		if destURL == "" || destURL[0] == '/' {
			destURL = "http://" + r.Host + r.URL.String()
		}

		// Create outbound request
		outReq, err := http.NewRequest(r.Method, destURL, r.Body)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}

		// Copy headers
		for k, v := range r.Header {
			outReq.Header[k] = v
		}
		outReq.Header.Set("X-Injected", "sekret")

		// Do request
		client := &http.Client{}
		resp, err := client.Do(outReq)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		defer resp.Body.Close()

		// Copy response headers
		for k, v := range resp.Header {
			w.Header()[k] = v
		}
		w.WriteHeader(resp.StatusCode)

		// Write body
		_, _ = httutil.Copy(w, resp.Body)
	})

	fmt.Printf("Proxy listening on %s\n", listen)
	if err := http.ListenAndServe(listen, nil); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
