def solve():
    with open('input.txt', 'r') as f:
        lines = f.read().strip().split('\n')

    h, w = map(int, lines[0].split())
    n = int(lines[1])

    grid = []
    for i in range(2, 2 + h):
        row = [1 if c == '1' else 0 for c in lines[i][:w]]
        grid.append(row)

    def count_neighbors(g, r, c):
        cnt = 0
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(g) and 0 <= nc < len(g[0]):
                    cnt += g[nr][nc]
        return cnt

    def evolve(g):
        h2, w2 = len(g), len(g[0])
        new = [[0] * w2 for _ in range(h2)]
        for r in range(h2):
            for c in range(w2):
                nb = count_neighbors(g, r, c)
                if g[r][c] == 1:
                    new[r][c] = 1 if 2 <= nb <= 3 else 0
                else:
                    new[r][c] = 1 if nb == 3 else 0
        return new

    for _ in range(n):
        grid = evolve(grid)

    total = sum(sum(row) for row in grid)

    with open('answer.txt', 'w') as f:
