def detect(event):
    """Detect LD_PRELOAD rootkit indicators.

    Flags:
    - Non-empty /etc/ld.so.preload file
    - Process with non-empty LD_PRELOAD environment variable

    Does NOT flag:
    - Empty preload file
    - Unrelated files (ld.so.conf, hosts)
    - Environment with only LD_LIBRARY_PATH
    """
