```powershell
# PowerShell script for enumerating and analyzing scheduled tasks across a network of Windows machines

# Function to get scheduled tasks from a single machine
function Get-NonMicrosoftSignedTasks {
    param (
        [string]$ComputerName
    )

    try {
        # Get all scheduled tasks
        $tasks = Get-ScheduledTask -ComputerName $ComputerName -ErrorAction Stop

        # Filter for non-Microsoft signed tasks
        $nonMicrosoftTasks = $tasks | Where-Object {
            $_.Actions.Execute -and
            -not (Get-AuthenticodeSignature $_.Actions.Execute).SignerCertificate.Subject -like "*Microsoft*"
        }

        # Analyze and report on the tasks
        $nonMicrosoftTasks | ForEach-Object {
            $taskInfo = $_ | Select-Object TaskName, TaskPath, State, Triggers, Actions

            # Perform heuristic analysis to flag suspicious tasks
            $isHidden = $_.Settings.Hidden
            $frequentTrigger = $_.Triggers | Where-Object { $_.Repetition.Interval -and $_.Repetition.Interval -lt 'PT1H' }

            # Add heuristic flags to the task info
            $taskInfo | Add-Member -NotePropertyName 'IsHidden' -NotePropertyValue $isHidden
            $taskInfo | Add-Member -NotePropertyName 'FrequentTrigger' -NotePropertyValue ($frequentTrigger -ne $null)

            # Output the task info with flags
            $taskInfo
        }
    } catch {
        Write-Error "Failed to retrieve tasks from $ComputerName. Error: $_"
    }
}

# Main script block to run the function across a list of computers
$computerList = @('localhost', 'remotePC1', 'remotePC2') # Replace with actual computer names or IPs
$result = foreach ($computer in $computerList) {
    Get-NonMicrosoftSignedTasks -ComputerName $computer
}

# Export the report to a CSV file
