# Function to check if a Conditional Access policy requires MFA
function Check-MFAInPolicy {
    param ($policy)

    $result = $false
    foreach ($grant in $policy.GrantControls.BuiltInControls) {
        if ($grant -eq "mfa") {
            $result = $true
            break
        }
    }
    return $result
}

# Function to check if an application has excessive permissions
function Check-ExcessivePermissions {
    param ($app)

    $excessivePermissions = @("User.Read.All", "Directory.Read.All", "Group.Read.All", "Device.Read.All", "Application.Read.All", "User.ReadWrite.All", "Directory.ReadWrite.All", "Group.ReadWrite.All", "Device.ReadWrite.All", "Application.ReadWrite.All")
    $permissions = $app.RequiredResourceAccess
    $excessivePermissionsFound = @()

    foreach ($permission in $permissions) {
        foreach ($excessivePermission in $excessivePermissions) {
            if ($permission.ResourceAccess.Id -eq $excessivePermission) {
                $excessivePermissionsFound += $permission
                break
            }
        }
    }

    return $excessivePermissionsFound
}

# Retrieve all Conditional Access policies
$allCA = Get-AzureADMSConditionalAccessPolicy

# Initialize counters
$mfaPolicyCount = 0
$excessivePermissionsCount = 0

# Initialize report array
$report = @()

# Check each Conditional Access policy for MFA and excessive permissions
foreach ($policy in $allCA) {
    $mfaRequired = Check-MFAInPolicy -policy $policy
    if ($mfaRequired) {
        $mfaPolicyCount++
    }

    $applications = Get-AzureADServicePrincipal -Filter "appId eq '$($policy.Conditions.Applications.IncludeApplications)'"
    foreach ($app in $applications) {
        $excessivePermissions = Check-ExcessivePermissions -app $app
        if ($excessivePermissions.Count -gt 0) {
