                AppName = $app.DisplayName
                Permissions = $excessivePermissions.ResourceAccess.Id -join ", "
                UsersOrGroups = (Get-AzureADServicePrincipalAppRoleAssignment -ObjectId $app.ObjectId).Count
            }
        }
    }
}

# Output the report
$report | Export-Csv -Path "AzureADSecurityReport.csv" -NoTypeInformation

# Output summary
Write-Host "Number of Conditional Access policies enforcing MFA: $mfaPolicyCount"
Write-Host "Number of applications with excessive permissions: $excessivePermissionsCount"
