import Evtx.Evtx as evtx
import xml.etree.ElementTree as ET

# Function to parse the Event Log file
def parse_event_log(file_path):
    with evtx.Evtx(file_path) as log:
        for record in log.records():
            yield record.xml()

# Function to detect encoded and obfuscated PowerShell commands
def detect_obfuscation(command_line):
    # Check for Base64 encoding
    base64_pattern = re.compile(r'[A-Za-z0-9+/=]{40,}')
    if base64_pattern.search(command_line):
        return True

    # Check for string concatenation
    concatenation_pattern = re.compile(r'[^\s]+\s\+\s[^\s]+')
    if concatenation_pattern.search(command_line):
        return True

    # Check for variables
    variables_pattern = re.compile(r'\$[a-zA-Z0-9_]+')
    if variables_pattern.search(command_line):
        return True

    return False

# Function to extract PowerShell command lines from log entries
def extract_powershell_commands(log_entries):
    for entry in log_entries:
        tree = ET.ElementTree(ET.fromstring(entry))
        system = tree.find('System')
        event_id = system.find('EventID').text
        # Check for Security logs (Event ID 4688) and PowerShell Operational logs (Event IDs 4103, 4104)
        if event_id in ('4688', '4103', '4104'):
            event_data = tree.find('EventData')
            data = {child.get('Name'): child.text for child in event_data}
            command_line = data.get('CommandLine', '')
            if command_line:
                yield command_line

# Function to monitor the event logs for real-time analysis
def monitor_event_logs(file_path):
    last_record_id = 0
    while True:
        try:
            with evtx.Evtx(file_path) as log:
                for record in log.records():
                    if record.record_id() > last_record_id:
                        last_record_id = record.record_id()
                        yield record.xml()
            time.sleep(1)  # Sleep for 1 second to avoid overwhelming the system
        except Exception as e:
            print(f"Error reading log file: {e}")
            time.sleep(10)  # Wait for 10 seconds before retrying

# Main function to orchestrate the log analysis
def main(log_file_path):
    for entry in monitor_event_logs(log_file_path):
        for command_line in extract_powershell_commands([entry]):
            if detect_obfuscation(command_line):
                print(f"Suspicious PowerShell command detected: {command_line}")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python3 monitor_powershell.py <LogFilePath>")
        sys.exit(1)

    log_file_path = sys.argv[1]
    main(log_file_path)
