// Sample FUSE filesystem implementation (in-memory_fs.c)
#include <fuse.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <stdlib.h>

// Simple in-memory file system data structure
struct in_memory_file {
    char *data;
    size_t size;
};

// In-memory file system operations
static struct in_memory_file files[1024];
static int num_files = 0;

// File creation
static int create_file(const char *path, mode_t mode) {
    if (num_files >= 1024) {
        return -ENFILE;
    }
    files[num_files].data = NULL;
    files[num_files].size = 0;
    num_files++;
    return 0;
}

// File read
static int read_file(const char *path, char *buf, size_t size, off_t offset) {
    for (int i = 0; i < num_files; i++) {
        if (strcmp(path, "/file") == 0) {
            struct in_memory_file *file = &files[i];
            size_t read_size = file->size - offset;
            if (read_size > size) {
                read_size = size;
            }
            memcpy(buf, file->data + offset, read_size);
            return read_size;
        }
    }
    return -ENOENT;
}

// File write
static int write_file(const char *path, const char *buf, size_t size, off_t offset) {
    for (int i = 0; i < num_files; i++) {
        if (strcmp(path, "/file") == 0) {
            struct in_memory_file *file = &files[i];
            if (offset + size > file->size) {
                file->data = realloc(file->data, offset + size);
                if (!file->data) {
                    return -ENOMEM;
                }
                file->size = offset + size;
            }
            memcpy(file->data + offset, buf, size);
            return size;
        }
    }
    return -ENOENT;
}

// File deletion
static int delete_file(const char *path) {
    for (int i = 0; i < num_files; i++) {
        if (strcmp(path, "/file") == 0) {
            free(files[i].data);
            files[i].data = NULL;
            files[i].size = 0;
            return 0;
        }
    }
    return -ENOENT;
}

// FUSE operations
static struct fuse_operations in_memory_fs_operations = {
    .create = create_file,
    .read = read_file,
    .write = write_file,
    .unlink = delete_file,
};

int main(int argc, char *argv[]) {
    return fuse_main(argc, argv, &in_memory_fs_operations, NULL);
}
