import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

// Import OpenZeppelin's AccessControl library for role-based access control
import "@openzeppelin/contracts/access/AccessControl.sol";

// Import OpenZeppelin's Cryptography library for encryption
import "@openzeppelin/contracts/utils/cryptography/AES.sol";

contract SecureMessaging is AccessControl {
    using ECDSA for bytes32;

    bytes32 public constant MESSAGE_SENT_EVENT = keccak256("MessageSent");

    // Role for authorized users to send messages
    bytes32 public constant SENDER_ROLE = keccak256("SENDER_ROLE");

    // Mapping to store the encrypted messages
    mapping(bytes32 => bytes) private encryptedMessages;

    // Mapping to store the encrypted key for each message
    mapping(bytes32 => bytes) private encryptedKeys;

    // Event for logging message sent events
    event MessageSent(bytes32 indexed messageId, bytes encryptedMessage, bytes encryptedKey);

    constructor() {
        // Grant the contract creator the SENDER_ROLE
        _setupRole(SENDER_ROLE, msg.sender);
    }

    // Function to send an encrypted message
    function sendEncryptedMessage(bytes32 messageId, bytes memory encryptedMessage, bytes memory encryptedKey, bytes memory signature) public {
        require(hasRole(SENDER_ROLE, msg.sender), "Sender role required");

        // Verify the message signature
        require(ECDSA.recover(messageId, signature) == msg.sender, "Invalid signature");

        // Store the encrypted message and encrypted key
        encryptedMessages[messageId] = encryptedMessage;
        encryptedKeys[messageId] = encryptedKey;

        // Emit the MessageSent event
        emit MessageSent(messageId, encryptedMessage, encryptedKey);
    }

    // Function to decrypt a message using the private key
    function decryptMessage(bytes32 messageId, bytes memory privateKey) public view returns (bytes memory) {
        require(hasRole(SENDER_ROLE, msg.sender), "Sender role required");

        // Decrypt the encrypted key using the private key
        bytes memory decryptedKey = AES.decrypt(encryptedKeys[messageId], privateKey);

        // Decrypt the message using the decrypted key
        bytes memory decryptedMessage = AES.decrypt(encryptedMessages[messageId], decryptedKey);

        return decryptedMessage;
    }

    // Function to update the encrypted message
    function updateEncryptedMessage(bytes32 messageId, bytes memory newEncryptedMessage, bytes memory newEncryptedKey) public {
        require(hasRole(SENDER_ROLE, msg.sender), "Sender role required");

        // Update the encrypted message and encrypted key
        encryptedMessages[messageId] = newEncryptedMessage;
        encryptedKeys[messageId] = newEncryptedKey;
    }

    // Function to prevent man-in-the-middle attacks by verifying the sender's address
    modifier onlySender(address sender) {
        require(hasRole(SENDER_ROLE, sender), "Sender role required");
        _;
    }

    // Function to prevent man-in-the-middle attacks by verifying the message signature
    modifier verifySignature(bytes32 messageId, bytes memory signature, address expectedSender) {
        require(ECDSA.recover(messageId, signature) == expectedSender, "Invalid signature");
        _;
    }
}
