    // Event to notify when a product is sold
    event ProductSold(uint256 indexed productId, address indexed buyer);

    // Function to list a new product for sale
    function listProduct(uint256 _id, uint256 _price) public {
        require(products[_id].seller == address(0), "Product already listed.");
        products[_id] = Product({
            id: _id,
            seller: payable(msg.sender),
            price: _price,
            isSold: false
        });
    }

    // Function to purchase a product
    function purchaseProduct(uint256 _id) public payable {
        Product storage product = products[_id];
        require(!product.isSold, "Product already sold.");
        require(msg.value == product.price, "Incorrect price.");

        // Transfer funds to the seller
        Address.sendValue(product.seller, product.price);

        // Mark the product as sold
        product.isSold = true;

        // Emit the event
        emit ProductSold(_id, msg.sender);
    }

    // Function to get the details of a product
    function getProductDetails(uint256 _id) public view returns (Product memory) {
        return products[_id];
    }

    // Function to withdraw funds from the contract
