        payable(owner()).transfer(address(this).balance);
    }

    // Function to modify the price of a listed product
    function updateProductPrice(uint256 _id, uint256 _newPrice) public {
        Product storage product = products[_id];
        require(product.seller == msg.sender, "Not the seller of the product.");
        require(!product.isSold, "Product already sold, cannot update price.");
        product.price = _newPrice;
    }

    // Function to remove a product listing
    function removeProduct(uint256 _id) public {
        Product storage product = products[_id];
        require(product.seller == msg.sender, "Not the seller of the product.");
        require(!product.isSold, "Product already sold, cannot remove listing.");
        delete products[_id];
    }

    // Fallback function to handle Ether sent to the contract
    receive() external payable {}
}
