        bytes32 transactionHash = keccak256(abi.encodePacked(msg.sender, _to, _amount, block.timestamp));

        // Store the transaction details
        transactions[transactionHash] = Transaction({
            from: msg.sender,
            to: _to,
            amount: _amount,
            timestamp: block.timestamp,
            transactionHash: transactionHash
        });

        // Emit an event for the transaction log
        emit TransactionLog(msg.sender, _to, _amount, block.timestamp);
    }

    // Function to retrieve a transaction record
    function getTransaction(bytes32 _transactionHash) public view returns (Transaction memory) {
        // Ensure the transaction exists
        require(transactions[_transactionHash].timestamp != 0, "Transaction does not exist");

        // Return the transaction
