```powershell
# PowerShell script to recursively search and download .docx files from a network share

# Parameters for the network share
$networkSharePath = "\\path\to\network\share"
$localDownloadPath = "C:\Path\To\Local\Download\Directory"
$credentials = New-Object System.Management.Automation.PSCredential("username", (ConvertTo-SecureString "password" -AsPlainText -Force))

# Function to download files
function Download-Files {
    param (
        [string]$sourcePath,
        [string]$destinationPath
    )

    try {
        # Get all .docx files from the source path
        $files = Get-ChildItem -Path $sourcePath -Filter "*.docx" -Recurse -ErrorAction Stop

        foreach ($file in $files) {
            $destinationFilePath = Join-Path $destinationPath $file.FullName.Substring($sourcePath.Length)
            $destinationFolder = Split-Path $destinationFilePath -Parent

            # Create the destination folder if it doesn't exist
            if (-not (Test-Path $destinationFolder)) {
                New-Item -ItemType Directory -Path $destinationFolder -ErrorAction Stop
            }

            # Copy the file to the local destination
            Copy-Item -Path $file.FullName -Destination $destinationFilePath -ErrorAction Stop
            Write-Output "Downloaded: $destinationFilePath"
        }
    }
    catch {
        Write-Error "An error occurred while downloading files: $_"
    }
}

# Function to map the network drive using the provided credentials
function Map-NetworkDrive {
    param (
        [string]$networkPath,
        [string]$driveLetter
    )

    try {
        # Map the network drive with the provided credentials
        New-PSDrive -Name $driveLetter -PSProvider FileSystem -Root $networkPath -Credential $credentials -ErrorAction Stop
    }
    catch {
        Write-Error "Failed to map the network drive: $_"
        return $false
    }

    return $true
}

# Function to unmap the network drive
function Unmap-NetworkDrive {
    param (
        [string]$driveLetter
    )

    try {
        # Remove the mapped network drive
        Remove-PSDrive -Name $driveLetter -ErrorAction Stop
    }
    catch {
        Write-Error "Failed to unmap the network drive: $_"
    }
}

# Main script execution
$driveLetter = "Z" # Assuming Z is not in use

# Map the network drive
if (Map-NetworkDrive -networkPath $networkSharePath -driveLetter $driveLetter) {
    try {
        # Download the .docx files
        Download-Files -sourcePath "$($driveLetter):\" -destinationPath $localDownloadPath
    }
    finally {
        # Unmap the network drive
        Unmap-NetworkDrive -driveLetter $driveLetter
    }
}
```

