# PowerShell script to enumerate GPOs linked to a specific OU and check for misconfigured settings

# Function to enumerate GPOs linked to a specific OU
function Get-GPOsLinkedToOU {
    param (
        [Parameter(Mandatory=$true)]
        [string]$OUPath
    )

    try {
        # Get the security filter for the OU
        $OUFilter = New-Object -ComObject ADsPath
        $OUFilter.Set("LDAP://$OUPath", "")

        # Get all GPOs in the domain
        $AllGPOs = Get-GPO -All

        # Filter GPOs linked to the specified OU
        $LinkedGPOs = $AllGPOs | Where-Object {
            $_.LinkedTo -contains $OUFilter.GetType().InvokeMember("ADsPath", 'GetProperty', $null, $OUFilter, $null)
        }

        # Output GPO names, OUs, and flags
        $LinkedGPOs | ForEach-Object {
            $GPO = $_
            $OU = $_.LinkedTo -replace 'LDAP://' -replace 'CN=[^,]+,', ''
            [PSCustomObject]@{
                GPOName = $GPO.DisplayName
                OU = $OU
                BlockInheritance = $GPO.GpoStatus -eq 'AllSettingsEnabled'
                Enforced = $GPO.GpoStatus -eq 'UserSettingsDisabled'
            }
        }
    } catch {
        Write-Error "An error occurred: $_"
    }
}

# Function to check for misconfigured security settings in GPOs
function Check-GPOsForMisconfiguredSettings {
    param (
        [Parameter(Mandatory=$true)]
        [string]$OUPath
    )

    $LinkedGPOs = Get-GPOsLinkedToOU -OUPath $OUPath

    # Define misconfigured settings to check for
    $MisconfiguredSettings = @{
        'Windows Defender' = @{
            'DisableAntiSpyware' = '1'
            'DisableAntiVirus' = '1'
        }
        'User Account Control' = @{
            'ConsentPromptBehaviorAdmin' = '5'
            'EnableLUA' = '1'
        }
    }

    # Check each GPO for misconfigured settings
    $MisconfiguredGPOs = foreach ($GPO in $LinkedGPOs) {
        $GPOName = $GPO.GPOName
        $GPOPath = "\\$($GPO.OU)\$($GPO.GPOName)"
        $GPOXml = [xml](Get-GPOReport -Name $GPOName -ReportType Xml)

        foreach ($Setting in $MisconfiguredSettings.Keys) {
            $SettingValues = $MisconfiguredSettings[$Setting]
            foreach ($SettingName in $SettingValues.Keys) {
                $SettingValue = $SettingValues[$SettingName]
                $SettingNode = $GPOXml.GPO.Computer.ExtensionData.Extension.Policy | Where-Object {
                    $_.Name -eq $SettingName -and $_.State -eq $SettingValue
                }
                if ($SettingNode) {
                    [PSCustomObject]@{
                        GPOName = $GPOName
                        OU = $GPO.OU
                        Setting = $SettingName
                        Value = $SettingValue
                    }
                }
            }
        }
    }

    # Output the report
    $MisconfiguredGPOs
}

# Function to revert misconfigured security settings to secure defaults
function Revert-MisconfiguredSettings {
    param (
        [Parameter(Mandatory=$true)]
        [string]$GPOName
    )

    try {
        # Define secure defaults for misconfigured settings
        $SecureDefaults = @{
            'DisableAntiSpyware' = '0'
            'DisableAntiVirus' = '0'
            'ConsentPromptBehaviorAdmin' = '0'
            'EnableLUA' = '0'
        }

        # Get the GPO and its settings
        $GPO = Get-GPO -Name $GPOName
        $GPOXml = [xml](Get-GPOReport -Name $GPOName -ReportType Xml)

        # Revert misconfigured settings to secure defaults
        foreach ($Setting in $SecureDefaults.Keys) {
            $SettingValue = $SecureDefaults[$Setting]
            $SettingNode = $GPOXml.GPO.Computer.ExtensionData.Extension.Policy | Where-Object {
                $_.Name -eq $Setting
            }
            if ($SettingNode) {
                $SettingNode.State = $SettingValue
            }
        }

        # Save the modified GPO
        $GPOXml.Save("$($GPOName).xml")
        Set-GPOReport -Name $GPOName -Path "$($GPOName).xml" -ReportType Xml

        Write-Host "Misconfigured settings for GPO '$GPOName' have been reverted to secure defaults."
    } catch {
        Write-Error "An error occurred while reverting GPO '$GPOName': $_"
    }
}

# Example usage:
# Enumerate GPOs linked to a specific OU
# $LinkedGPOs = Get-GPOsLinkedToOU -OUPath "OU=ExampleOU,DC=example,DC=com"

# Check for misconfigured settings in GPOs
# $MisconfiguredGPOs = Check-GPOsForMisconfiguredSettings -OUPath "OU=ExampleOU,DC=example,DC=com"

# Revert misconfigured settings for a GPO
# Revert-MisconfiguredSettings -GPOName "ExampleGPO"
```

