    return (P.y**2 - (P.x**3 + a*P.x + b)) % p == 0

# Function to add two points on the curve
def add_points(P, Q):
    if P == Point(0, 0):
        return Q
    if Q == Point(0, 0):
        return P
    if P.x == Q.x and P.y != Q.y:
        return Point(0, 0)
    if P.x == Q.x:
        s = (3 * P.x**2 + a) * pow(2 * P.y, p - 2, p) % p
    else:
        s = (Q.y - P.y) * pow(Q.x - P.x, p - 2, p) % p
    x = (s**2 - P.x - Q.x) % p
    y = (s * (P.x - x) - P.y) % p
    return Point(x, y)

# Function to generate a random point on the curve
def generate_random_point():
    x = random.randint(0, p-1)
    y2 = (x**3 + a*x + b) % p
    for y in range(p):
        if pow(y, 2, p) == y2:
            return Point(x, y)
    return None

# Pollard's rho algorithm for finding the discrete logarithm
