    f = lambda x: (x * 2) % (p - 1)
    x = random.randint(0, p-1)
    y = x
    d = 1
    while d == 1:
        x = f(x)
        y = f(f(y))
        d = gcd(abs(x - y), p - 1)
    if d == p - 1:
        return None
    l = (x - y) * pow(d, p - 2, p) % (p - 1)
    return l

# Helper function to find the greatest common divisor
