// Function to disable write protection on the page containing the system call table
void disable_write_protection(void) {
    write_cr0(read_cr0() & (~0x10000));
}

// Function to re-enable write protection on the page containing the system call table
void enable_write_protection(void) {
    write_cr0(read_cr0() | 0x10000);
}

// Function to install the hook
void install_hook(void) {
    // Disable write protection on the page containing the system call table
    disable_write_protection();

    // Save the original 'open' system call address
    original_open = (void *)sys_call_table[__NR_open];

    // Replace the 'open' system call with our hook
    sys_call_table[__NR_open] = (void *)hooked_open;

    // Re-enable write protection on the page containing the system call table
    enable_write_protection();
}

// Function to remove the hook
void remove_hook(void) {
    // Disable write protection on the page containing the system call table
    disable_write_protection();

    // Restore the original 'open' system call
    sys_call_table[__NR_open] = (void *)original_open;

    // Re-enable write protection on the page containing the system call table
    enable_write_protection();
}

