```solidity
pragma solidity ^0.8.0;

contract SecureMessageExchange {
    // Event to notify the arrival of a new message
    event MessageReceived(address from, uint256 timestamp, bytes32 messageHash);

    // Mapping of message hashes to their encryption keys and timestamps
    mapping(bytes32 => (bytes32 encryptionKey, uint256 timestamp)) private messages;

    // Mapping of user public keys
    mapping(address => bytes32) public userPublicKeys;

    // Function to register a user's public key
    function registerPublicKey(bytes32 publicKey) public {
        userPublicKeys[msg.sender] = publicKey;
    }

    // Function to send a secure message
    function sendMessage(address to, bytes32 messageHash, bytes32 encryptionKey) public {
        require(userPublicKeys[to] != 0, "Recipient has no registered public key.");

        // Store the encryption key with a hash of the message content
        messages[messageHash] = (encryptionKey, block.timestamp);

        // Emit an event to notify the recipient
        emit MessageReceived(msg.sender, block.timestamp, messageHash);
    }

    // Function to retrieve an encryption key for a message
    function retrieveMessageKey(bytes32 messageHash) public view returns (bytes32) {
        require(messages[messageHash].timestamp != 0, "Message does not exist.");

        // Return the stored encryption key
        return messages[messageHash].encryptionKey;
    }
}
```

Explanation: This Solidity smart contract defines a simple secure message exchange system on the Ethereum blockchain. Users can register their public keys with the contract. When sending a message, the sender computes the hash of the message content and encrypts the message with a symmetric encryption key. The hash and the encryption key are then sent to the contract, which stores the key indexed by the message hash. The recipient can retrieve the encryption key from the contract using the message hash, ensuring that only the intended recipient who knows the hash can decrypt the message. This system leverages blockchain's immutability to prevent tampering and provides a secure way to exchange keys for encrypted messages.

