        uint256 recordId = ++recordIdCounters[msg.sender];

        // Store the medical record
        records[msg.sender][recordId] = MedicalRecord({
            hash: hash,
            encryptedData: encryptedData,
            timestamp: block.timestamp
        });

        // Emit an event to notify the addition of a new record
        emit RecordAdded(msg.sender, recordId);
    }

    // Function to update an existing medical record
    function updateMedicalRecord(uint256 recordId, bytes memory encryptedData, bytes32 hash) public {
        require(patientPublicKeys[msg.sender] != 0, "Patient has not registered their public key.");
        require(records[msg.sender][recordId].timestamp != 0, "Record does not exist.");

        // Update the medical record
        records[msg.sender][recordId].encryptedData = encryptedData;
        records[msg.sender][recordId].hash = hash;
        records[msg.sender][recordId].timestamp = block.timestamp;

        // Emit an event to notify the update of a record
        emit RecordUpdated(msg.sender, recordId, block.timestamp);
    }

    // Function to retrieve a medical record
    function getMedicalRecord(address patient, uint256 recordId) public view returns (bytes memory, bytes32, uint256) {
        require(records[patient][recordId].timestamp != 0, "Record does not exist.");

        // Return the medical record details
        return (records[patient][recordId].encryptedData, records[patient][recordId].hash, records[patient][recordId].timestamp);
    }

    // Function to retrieve the record ID counter for a patient
    function getRecordIdCounter(address patient) public view returns (uint256) {
        return recordIdCounters[patient];
    }
}
