from scapy.all import *
import ipaddress

def ping_host(ip):
    try:
        # Send ICMP packet and wait for a reply
        response = sr1(IP(dst=str(ip))/ICMP(), timeout=1, verbose=0)
        if response:
            # Check for ICMP echo reply
            if response.haslayer(ICMP) and response.getlayer(ICMP).type == 0:
                return response.ttl
            elif response.haslayer(ICMP) and response.getlayer(ICMP).type == 11:
                # Time exceeded message, indicating a router or other device
                return 255
        else:
            # No response, host is down or filtered
            return None
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

def scan_subnet(subnet):
    active_hosts = {}
    for ip in ipaddress.IPv4Network(subnet):
        ttl = ping_host(ip)
        if ttl is not None:
            active_hosts[str(ip)] = ttl
    return active_hosts

