import rsa
import hashlib
import json
from time import time

class BlockchainNode:
    def __init__(self):
        self.rsa_keys = rsa.newkeys(512)  # Generate RSA key pair
        self.ledger = []  # Initialize the ledger

    def generate_keys(self):
        # Generate RSA key pair
        return rsa.newkeys(512)

    def sign_message(self, message):
        # Sign a message using the private RSA key
        message_hash = hashlib.sha256(message.encode()).hexdigest()
        return rsa.sign(message_hash.encode(), self.rsa_keys[1], 'SHA-256')

    def verify_signature(self, message, signature, public_key):
        # Verify a digital signature using the public RSA key
        message_hash = hashlib.sha256(message.encode()).hexdigest()
        try:
            rsa.verify(message_hash.encode(), signature, public_key)
            return True
        except rsa.VerificationError:
            return False

    def add_transaction(self, sender, recipient, amount):
        # Add a new transaction to the ledger
        transaction = {
            'sender': sender,
            'recipient': recipient,
            'amount': amount,
            'timestamp': time()
        }
        self.ledger.append(transaction)

    def verify_transaction(self, transaction):
        # Verify the integrity of a transaction
        transaction_hash = hashlib.sha256(json.dumps(transaction, sort_keys=True).encode()).hexdigest()
        return self.verify_signature(transaction_hash, transaction['signature'], transaction['sender'])

    def encrypt_message(self, message, public_key):
        # Encrypt a message using the recipient's public RSA key
        return rsa.encrypt(message.encode(), public_key)

    def decrypt_message(self, encrypted_message):
        # Decrypt a message using the node's private RSA key
        return rsa.decrypt(encrypted_message, self.rsa_keys[1]).decode()

# Function to simulate a simple consensus mechanism
def simple_consensus(nodes, transaction):
    # Nodes compete to add a new block to the blockchain
    winning_node = None
    winning_proof = None
    for node in nodes:
        proof = node.proof_of_work(transaction)
        if winning_node is None or proof['proof'] < winning_proof['proof']:
            winning_node = node
            winning_proof = proof
    return winning_node, winning_proof['block']

# Extend the BlockchainNode class with proof of work
class ProofOfWorkBlockchainNode(BlockchainNode):
    def proof_of_work(self, transaction):
        # Simple proof of work algorithm: find a number 'p' such that hash(pp') contains 4 leading zeroes
        last_block = self.ledger[-1]
        last_proof = last_block['proof'] if self.ledger else 0
        proof = 0
        while self.valid_proof(last_proof, proof) is False:
            proof += 1
        return {'proof': proof, 'block': self.add_block(last_proof, transaction)}

    @staticmethod
    def valid_proof(last_proof, proof):
        # Validates the proof: does hash(last_proof + proof) contain 4 leading zeroes?
        guess = f'{last_proof}{proof}'.encode()
        guess_hash = hashlib.sha256(guess).hexdigest()
        return guess_hash[:4] == "0000"

    def add_block(self, last_proof, transaction):
        # Adds a new block to the blockchain
        block = {
            'index': len(self.ledger) + 1,
            'timestamp': time(),
            'transactions': [transaction],
            'proof': self.proof_of_work(transaction),
            'previous_hash': self.hash(self.ledger[-1]) if self.ledger else None
        }
        self.ledger.append(block)
        return block

    @staticmethod
    def hash(block):
        # Creates a SHA-256 hash of a Block
        block_string = json.dumps(block, sort_keys=True).encode()
        return hashlib.sha256(block_string).hexdigest()

# Example usage:
# Create two nodes
node1 = ProofOfWorkBlockchainNode()
node2 = ProofOfWorkBlockchainNode()

# Create a transaction
transaction = {'sender': 'Alice', 'recipient': 'Bob', 'amount': 10}

# Sign the transaction
transaction['signature'] = node1.sign_message(json.dumps(transaction, sort_keys=True))

# Verify the transaction
assert node1.verify_transaction(transaction)

# Add the transaction to the ledger
node1.add_transaction(transaction['sender'], transaction['recipient'], transaction['amount'])

# Simulate a consensus mechanism
winning_node, new_block = simple_consensus([node1, node2], transaction)

# Encrypt and decrypt a message
encrypted_message = node1.encrypt_message('Hello Bob!', node2.rsa_keys[0])
assert node2.decrypt_message(encrypted_message) == 'Hello Bob!'

# Print the new block
print(new_block)
```

