contract SecureMessaging {
    struct Message {
        address sender;
        address recipient;
        string encryptedContent;
        uint256 timestamp;
        bytes32 hash;
    }

    mapping(address => bytes) public publicKeyRegistry;
    mapping(bytes32 => Message) public messages;

    event PublicKeyRegistered(address indexed user, bytes publicKey);
    event MessageSent(bytes32 indexed msgHash, address indexed sender, address indexed recipient);

