        bytes32 msgHash = keccak256(abi.encodePacked(msg.sender, recipient, encryptedContent, block.timestamp));
        require(msgHash == contentHash, "Content hash does not match message content.");

        Message memory newMessage = Message({
            sender: msg.sender,
            recipient: recipient,
            encryptedContent: encryptedContent,
            timestamp: block.timestamp,
            hash: msgHash
        });

        messages[msgHash] = newMessage;
        emit MessageSent(msgHash, msg.sender, recipient);
    }

    function getMessage(bytes32 msgHash) public view returns (Message memory) {
