contract SecureTransactionLog {
    using SafeMath for uint256;

    // Event to log a transaction with its details
    event TransactionLogged(
        address indexed sender,
        address indexed recipient,
        uint256 amount,
        uint256 timestamp,
        bytes32 indexed transactionHash
    );

    // Mapping to store the transaction details
    mapping(bytes32 => Transaction) private transactions;

    // Structure to hold transaction details
    struct Transaction {
        address sender;
        address recipient;
        uint256 amount;
        uint256 timestamp;
    }

    // Function to log a transaction with its details
    function logTransaction(
        address _sender,
        address _recipient,
        uint256 _amount
    ) public {
        // Generate a unique identifier for the transaction using keccak256 hash function
        bytes32 transactionHash = keccak256(
            abi.encodePacked(
                _sender,
                _recipient,
                _amount,
                block.timestamp
            )
        );

        // Store the transaction details in the mapping
        transactions[transactionHash] = Transaction({
            sender: _sender,
            recipient: _recipient,
            amount: _amount,
            timestamp: block.timestamp
        });

        // Emit the TransactionLogged event
        emit TransactionLogged(
            _sender,
            _recipient,
            _amount,
            block.timestamp,
            transactionHash
        );
    }

    // Function to retrieve the transaction details by providing the hash of the transaction
    function getTransaction(bytes32 _transactionHash)
        public
        view
        returns (Transaction memory)
    {
        return transactions[_transactionHash];
    }

    // Function to verify the authenticity of the transaction data
    function verifyTransaction(
        address _sender,
        address _recipient,
        uint256 _amount,
        uint256 _timestamp,
        bytes32 _transactionHash
    ) public pure returns (bool) {
        // Recalculate the hash of the provided transaction details
        bytes32 calculatedHash = keccak256(
            abi.encodePacked(_sender, _recipient, _amount, _timestamp)
        );

        // Check if the calculated hash matches the provided hash
        return calculatedHash == _transactionHash;
    }
}
