// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract Auction {
    // Auction parameters
    address payable public owner;
    uint256 public auctionEnd;
    uint256 public highestBid;
    address public highestBidder;
    bool public ended;

    // Event to indicate a new bid has been placed
    event BidPlaced(address bidder, uint256 bidAmount);

    // Event to indicate the auction has ended and the highest bidder has been determined
    event AuctionEnded(address winner, uint256 winningBid);

    // Modifier to ensure the auction is still ongoing
    modifier onlyBefore(uint256 time) {
        require(time <= block.timestamp, "Auction not started yet");
        _;
    }

    // Modifier to ensure the auction has ended
    modifier onlyAfter(uint256 time) {
        require(time >= block.timestamp, "Auction not ended yet");
        _;
    }

    constructor(uint256 _biddingTime) {
        owner = payable(msg.sender);
        auctionEnd = block.timestamp + _biddingTime;
    }

    // Place a bid on the auction
    function bid() public payable onlyBefore(auctionEnd) {
        require(msg.value > highestBid, "Bid must be higher than current highest bid");
        if (highestBidder != address(0)) {
            // Refund the previously highest bidder
            payable(highestBidder).transfer(highestBid);
        }
        highestBidder = msg.sender;
        highestBid = msg.value;
        emit BidPlaced(msg.sender, msg.value);
    }

    // End the auction and send the item to the highest bidder
    function auctionEnded() public onlyAfter(auctionEnd) {
        require(!ended, "Auction already ended");
        ended = true;
        payable(highestBidder).transfer(highestBid);
        emit AuctionEnded(highestBidder, highestBid);
    }

    // Get the current auction state
    function getAuctionState() public view returns (uint256, uint256, address, bool) {
        return (auctionEnd, highestBid, highestBidder, ended);
    }

    // Function to withdraw the contract balance
    function withdraw() public onlyAfter(auctionEnd) {
        require(msg.sender == owner, "Only owner can withdraw");
        owner.transfer(address(this).balance);
    }
}
```

This Solidity code snippet provides a basic implementation of an auction smart contract. It includes functionality for placing bids, ending the auction, getting the current auction state, and withdrawing funds. The contract ensures that only the highest bidder can withdraw the funds after the auction ends and that bids are placed securely and transparently.

