import os
import re

# Define a function to search for hardcoded credentials within a file
def search_credentials(file_path):
    # Regular expressions to match common patterns for credentials
    patterns = {
        'username': r'(?i)user(name)?\s*=\s*["\']?([\w.-]+)["\']?',
        'password': r'(?i)pass(word)?\s*=\s*["\']?([\w.-]+)["\']?',
        'api_key': r'(?i)api(key)?\s*=\s*["\']?([\w.-]+)["\']?',
        'secret': r'(?i)secret\s*=\s*["\']?([\w.-]+)["\']?'
    }

    # Dictionary to store found credentials
    credentials = {key: [] for key in patterns}

    try:
        with open(file_path, 'r', errors='ignore') as file:
            for line in file:
                for cred_type, pattern in patterns.items():
                    matches = re.findall(pattern, line)
                    if matches:
                        # Append unique matches to the credentials dictionary
                        for match in matches:
                            if match[0] not in credentials[cred_type]:
                                credentials[cred_type].append(match[0])
    except Exception as e:
        print(f"Error reading file {file_path}: {e}")

    return credentials

# Define a function to search for credentials in all files within a directory
def search_directory(directory):
    all_credentials = {
        'username': [],
        'password': [],
        'api_key': [],
        'secret': []
    }

    for root, dirs, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            file_credentials = search_credentials(file_path)
            for cred_type, creds in file_credentials.items():
                all_credentials[cred_type].extend(creds)

    return all_credentials

# Main function to run the script
