    $scriptBlock = $eventXml.Event.EventData.Data | Where-Object { $_.Name -eq 'ScriptBlockText' }
    $commandText = $scriptBlock.'#text'

    # Check if the command is whitelisted
    if (Is-WhitelistedCommand -command $commandText) {
        continue
    }

    # Decode base64 encoded strings
    $decodedCommandText = Decode-Base64String -encodedString $commandText

    # Create a custom object for the report
    [PSCustomObject]@{
        TimeCreated = $event.TimeCreated
        Account = $event.Properties[1].Value
        Command = $commandText
        DecodedCommand = $decodedCommandText
    }
}

# Output the report
$report | Format-Table -AutoSize

# Save the report to a file if needed
$report | Export-Csv -Path "PowerShell_Activity_Report.csv" -NoTypeInformation
