import os
import re
import subprocess
from androguard.core.bytecodes.apk import APK

# Function to extract the APK file
def extract_apk(apk_path):
    """
    Extracts the APK file using apktool and returns the path to the extracted directory.
    """
    extracted_path = "extracted_apk"
    if not os.path.exists(extracted_path):
        os.makedirs(extracted_path)
    subprocess.run(["apktool", "d", apk_path, "-o", extracted_path], check=True)
    return extracted_path

# Function to search for hardcoded sensitive information
def search_sensitive_info(extracted_path):
    """
    Searches through the decompiled source code for hardcoded sensitive information
    such as API keys, URLs, and other security tokens.
    """
    # Define patterns that may indicate hardcoded sensitive information
    patterns = {
        "API_KEY": r'(?i)(api_key|apikey|access_token|accesstoken)\s*=\s*["\'][^"\']+["\']',
        "URL": r'(?i)(https?://[^\s]+)'
    }
    sensitive_info = {}
    for root, dirs, files in os.walk(extracted_path):
        for file in files:
            if file.endswith(".smali"):
                file_path = os.path.join(root, file)
                with open(file_path, 'r') as f:
                    code = f.read()
                    for key, pattern in patterns.items():
                        if re.search(pattern, code):
                            if key not in sensitive_info:
                                sensitive_info[key] = []
                            sensitive_info[key].append(file_path)
    return sensitive_info

# Function to perform heuristic analysis
def heuristic_analysis(extracted_path):
    """
    Performs a heuristic analysis to detect potential malicious code patterns
    such as suspicious method calls, obfuscated code, or code that attempts to hide its presence.
    """
    # Define suspicious patterns
    suspicious_patterns = {
        "obfuscated_code": r'(Landroid/os/System;->loadLibrary)|(Landroid/os/System;->getenv)',
        "hidden_code": r'Landroid/os/System;->getenv'
    }
    findings = {}
    for root, dirs, files in os.walk(extracted_path):
        for file in files:
            if file.endswith(".smali"):
                file_path = os.path.join(root, file)
                with open(file_path, 'r') as f:
                    code = f.read()
                    for pattern_name, pattern in suspicious_patterns.items():
                        if re.search(pattern, code):
                            if pattern_name not in findings:
                                findings[pattern_name] = []
                            findings[pattern_name].append(file_path)
    return findings

# Main function to perform the analysis
def main(apk_path):
    """
    The main function that performs the static analysis tasks on the APK file.
    """
    extracted_path = extract_apk(apk_path)
    sensitive_info = search_sensitive_info(extracted_path)
    findings = heuristic_analysis(extracted_path)

    # Output the results
    print("Sensitive Information Found:")
    for key, paths in sensitive_info.items():
        print(f"{key}: {len(paths)} occurrences")

    print("\nHeuristic Analysis Findings:")
    for pattern_name, paths in findings.items():
        print(f"{pattern_name}: {len(paths)} occurrences")

# Example usage
