        Message memory newMessage = Message({
            encryptedMessage: encryptedMessage,
            sender: msg.sender,
            recipient: recipient,
            isDecrypted: false
        });
        messageCounter.increment();
        uint256 messageId = messageCounter.current();
        messages[messageId] = newMessage;
        emit MessageSent(messageId, msg.sender, recipient);
    }

    // Function to decrypt a message
    function decryptMessage(uint256 messageId) public view returns (bytes memory) {
        require(messages[messageId].sender == msg.sender, "Not the sender");
        require(messages[messageId].recipient == msg.sender, "Not the recipient");
        require(!messages[messageId].isDecrypted, "Message already decrypted");
        // Assume the private key is securely stored in the contract
        bytes memory privateKey = new bytes(32);
        // Decrypt the message using the private key
        bytes memory decryptedMessage = decrypt(privateKey, messages[messageId].encryptedMessage);
        emit MessageReceived(messageId, msg.sender, messages[messageId].sender);
        return decryptedMessage;
    }

    // Function to encrypt a message with a recipient's public key
    function encrypt(bytes memory publicKey, bytes memory message) internal pure returns (bytes memory) {
        // In practice, this would involve using an asymmetric encryption algorithm like ECIES
        // Here we simulate the encryption process
        return keccak256(abi.encodePacked(publicKey, message));
    }

    // Function to decrypt a message with the recipient's private key
    function decrypt(bytes memory privateKey, bytes memory encryptedMessage) internal pure returns (bytes memory) {
        // In practice, this would involve using the corresponding decryption algorithm
        // Here we simulate the decryption process
        return keccak256(abi.encodePacked(privateKey, encryptedMessage));
    }

    // Function to check if a message has been decrypted
    function isDecrypted(uint256 messageId) public view returns (bool) {
        return messages[messageId].isDecrypted;
    }

    // Function to retrieve an encrypted message
    function getEncryptedMessage(uint256 messageId) public view returns (bytes memory) {
        return messages[messageId].encryptedMessage;
    }
}
