pragma solidity ^0.8.0;

contract SecureMessaging {
    // Event to notify the arrival of a new message
    event MessageReceived(address indexed from, bytes32 indexed messageId);

    // Mapping of message IDs to message contents and metadata
    mapping(bytes32 => Message) public messages;

    struct Message {
        address sender;
        string content;
        uint256 timestamp;
        bool isRead;
    }

    // Function to send a message
    function sendMessage(address _to, string memory _content) public {
        // Generate a unique message ID
        bytes32 messageId = keccak256(abi.encodePacked(msg.sender, _to, _content, block.timestamp));
        // Store the message in the blockchain
        messages[messageId] = Message(msg.sender, _content, block.timestamp, false);
        // Emit an event for the recipient to be notified
        emit MessageReceived(_to, messageId);
    }

    // Function for the recipient to mark a message as read
    function markMessageAsRead(bytes32 _messageId) public {
        require(messages[_messageId].sender != address(0), "Message does not exist.");
        require(messages[_messageId].isRead == false, "Message already marked as read.");
        messages[_messageId].isRead = true;
    }
}

