// Importing OpenZeppelin's Ownable contract for access control
import "@openzeppelin/contracts/access/Ownable.sol";

// Contract inheriting from Ownable to ensure that only the contract owner can verify events
contract SecureEventLog is Ownable {
    // Structure to hold event data
    struct Event {
        uint256 timestamp;
        address sender;
        string eventType;
        string eventData;
        bytes32 hash;
        bool verified;
    }

    // Mapping of event hashes to event details
    mapping(bytes32 => Event) public events;

    // Event for logging new events
    event NewEventLogged(bytes32 indexed eventHash);

    // Event for verifying an event
    event EventVerified(bytes32 indexed eventHash);

    // Function to log a new event
    function logEvent(string memory _eventType, string memory _eventData) public {
        // Generate a unique hash for the event
        bytes32 eventHash = keccak256(abi.encodePacked(block.timestamp, msg.sender, _eventType, _eventData));
        // Create a new event
        Event memory newEvent = Event({
            timestamp: block.timestamp,
            sender: msg.sender,
            eventType: _eventType,
            eventData: _eventData,
            hash: eventHash,
            verified: false // Initially not verified
        });
        // Store the event in the blockchain
        events[eventHash] = newEvent;
        // Emit an event for others to listen to
        emit NewEventLogged(eventHash);
    }

    // Function to verify an event
    function verifyEvent(bytes32 _eventHash) public onlyOwner {
        require(events[_eventHash].verified == false, "Event has already been verified.");
        events[_eventHash].verified = true;
        emit EventVerified(_eventHash);
    }
}
